INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (366460, 15340, 'South China Morning Post', 'en', 'Zhipu AI’s answer to Project Glasswing marks shift for Chinese cyber safety: researcher', 'https://www.scmp.com/tech/article/3364356/zhipu-ais-answer-project-glasswing-marks-shift-chinese-cyber-safety-researcher', 'Zhipu AI’s launch of China’s first answer to Project Glasswing signals a shift in how the country’s top artificial intelligence labs approach global cybersecurity, according to a researcher. The Beijing-based firm – now known internationally as Z.ai – announced its new GLM-5.3 model on Friday alongside the launch of its “Shield of Open Source” initiative. The programme offers free security audits to help users patch software vulnerabilities, as well as automated code-auditing tools via its ZCode...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/18/9d0c3953-652c-44c9-ab1d-93ea7d9a8356_1e3df32f.jpg?itok=f93507lx&v=1787019285', '2026-08-18T03:00:14+00:00', '2026-08-18T03:12:26.895835'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (366468, 15340, 'South China Morning Post', 'en', 'Chinese workers turn bosses into virtual pets for stress relief amid rising quirky trend', 'https://www.scmp.com/news/people-culture/trending-china/article/3364350/chinese-workers-turn-bosses-virtual-pets-stress-relief-amid-rising-quirky-trend', 'AI desktop pets are gaining popularity in China, offering young workers an outlet for workplace frustration and providing bereaved owners with a digital means to preserve memories of their deceased pets. Virtual pets first emerged on messaging platforms in the early 2000s, roaming across screens and interacting with users as they browsed the web, chatted, or watched videos. Advancements in AI are evolving virtual pets from simple digital novelties into more responsive forms of emotional...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/18/976d2dc5-5751-4a39-ad04-c4dcbac59c1d_aa4733a4.jpg?itok=sWSloGyI&v=1787014825', '2026-08-18T01:00:32+00:00', '2026-08-18T03:12:26.990250'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
