INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (367211, 15340, 'South China Morning Post', 'en', 'Why is Chinese state media telling people to stop using English AI terms?', 'https://www.scmp.com/news/china/politics/article/3364320/why-chinese-state-media-telling-people-stop-using-english-ai-terms', 'China’s state media has called for English-language terms related to artificial intelligence (AI) to be dropped in favour of standardised Chinese equivalents in a push to boost the country’s “discourse power”. As AI technologies have rapidly spread in China, English terms have entered common speech in the country, such as “agent” and “LLM” for large language model, a commentary published by the Communist Party mouthpiece People’s Daily noted earlier this month. The article argued that reliance...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/17/e8df6cdc-4db4-4d0a-8b9c-dc991af8d52e_54974d48.jpg?itok=yhGM_t5n&v=1786967174', '2026-08-18T04:00:11+00:00', '2026-08-18T04:05:07.822004'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
